from watcher_runtime import harness
from watcher_runtime.adapters import ics_calendar

URL = "https://calendar.google.com/calendar/ical/de.german%23holiday%40group.v.calendar.google.com/public/basic.ics"

try:
    result = ics_calendar.fetch(URL)
except Exception as exc:
    harness.fail("I couldn't read the calendar just now.")
else:
    current_events = result.get("events", [])
    state = harness.load_state()
    previous_events = state.get("events")
    harness.save_state({"events": current_events})
    if previous_events is None:
        # first run, no baseline yet
        harness.emit("ok", "Calendar loaded, watching for changes.", "school calendar", next_check_s=3600)
    elif previous_events != current_events:
        harness.emit(
            "act_now",
            "The parents' evening calendar has changed. Check your schedule.",
            "school calendar",
            {"previous_count": len(previous_events), "current_count": len(current_events)},
            next_check_s=3600
        )
    else:
        harness.emit("ok", "No change in the parents' evening calendar.", "school calendar", next_check_s=3600)
